package com.bank.diversity.service;

import com.bank.diversity.dto.GenderReport;
import com.bank.diversity.model.Employee;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import java.math.BigDecimal;
import java.util.*;
import java.util.stream.Collectors;

@Service
@Slf4j
public class GenderCountService {

    private final List<Employee> employees = List.of(
        new Employee("E001", "Rajesh Kumar",  "TRADING",    "M", 35, new BigDecimal("1200000")),
        new Employee("E002", "Priya Sharma",  "RISK",       "F", 28, new BigDecimal("1000000")),
        new Employee("E003", "Amit Patel",    "TRADING",    "M", 52, new BigDecimal("1500000")),
        new Employee("E004", "Deepa Reddy",   "OPERATIONS", "F", 45, new BigDecimal("900000")),
        new Employee("E005", "Vikram Singh",  "RISK",       "M", 55, new BigDecimal("1800000")),
        new Employee("E006", "Neha Gupta",    "TRADING",    "F", 32, new BigDecimal("1100000")),
        new Employee("E007", "Suresh Iyer",   "OPERATIONS", "M", 58, new BigDecimal("1400000")),
        new Employee("E008", "Kavita Joshi",  "RISK",       "F", 41, new BigDecimal("950000")),
        new Employee("E009", "Rohit Mehta",   "COMPLIANCE", "M", 48, new BigDecimal("1300000")),
        new Employee("E010", "Anita Desai",   "COMPLIANCE", "F", 37, new BigDecimal("1050000"))
    );

    public GenderReport generateGenderReport() {

        // ═══ 1. ORGANIZATION-WIDE: gender count ═══
        Map<String, Long> orgWide = employees.stream()
            .collect(Collectors.groupingBy(Employee::gender, Collectors.counting()));
        log.info("Org-wide gender: {}", orgWide);

        // ═══ 2. PER-DEPARTMENT: nested groupingBy ═══
        Map<String, Map<String, Long>> perDept = employees.stream()
            .collect(Collectors.groupingBy(Employee::department, TreeMap::new,
                Collectors.groupingBy(Employee::gender, Collectors.counting())));
        log.info("Per-department gender: {}", perDept);

        // ═══ 3. PARTITIONING: boolean male vs female ═══
        Map<Boolean, Long> maleVsFemale = employees.stream()
            .collect(Collectors.partitioningBy(Employee::isMale, Collectors.counting()));
        log.info("Male(true) vs Female(false): {}", maleVsFemale);

        // ═══ 4. IMBALANCED DEPARTMENTS (>70% one gender) ═══
        List<String> imbalanced = perDept.entrySet().stream()
            .filter(entry -> {
                long total = entry.getValue().values().stream().mapToLong(Long::longValue).sum();
                long maxGender = entry.getValue().values().stream().mapToLong(Long::longValue).max().orElse(0);
                return total > 0 && (double) maxGender / total > 0.70;
            })
            .map(entry -> entry.getKey() + ": " + entry.getValue())
            .toList();
        log.info("Imbalanced departments: {}", imbalanced);

        return new GenderReport(orgWide, perDept, maleVsFemale, imbalanced);
    }
}
