package com.bank.diversity.service;

import com.bank.diversity.model.Employee;
import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import java.util.*;
import java.util.stream.Collectors;
import static org.assertj.core.api.Assertions.*;

class GenderCountTest {

    List<Employee> emps = List.of(
        new Employee("E1", "Rajesh", "TRADING", "M", 35, BigDecimal.valueOf(1200000)),
        new Employee("E2", "Priya", "TRADING", "F", 28, BigDecimal.valueOf(1000000)),
        new Employee("E3", "Amit", "RISK", "M", 52, BigDecimal.valueOf(1500000)),
        new Employee("E4", "Deepa", "RISK", "F", 45, BigDecimal.valueOf(900000)),
        new Employee("E5", "Vikram", "RISK", "M", 55, BigDecimal.valueOf(1800000))
    );

    @Test
    void orgWideGenderCount() {
        Map<String, Long> count = emps.stream()
            .collect(Collectors.groupingBy(Employee::gender, Collectors.counting()));
        assertThat(count).containsEntry("M", 3L).containsEntry("F", 2L);
    }

    @Test
    void perDepartmentGenderCount() {
        Map<String, Map<String, Long>> perDept = emps.stream()
            .collect(Collectors.groupingBy(Employee::department,
                Collectors.groupingBy(Employee::gender, Collectors.counting())));
        assertThat(perDept.get("TRADING")).containsEntry("M", 1L).containsEntry("F", 1L);
        assertThat(perDept.get("RISK")).containsEntry("M", 2L).containsEntry("F", 1L);
    }

    @Test
    void partitioningByGender() {
        Map<Boolean, Long> partition = emps.stream()
            .collect(Collectors.partitioningBy(Employee::isMale, Collectors.counting()));
        assertThat(partition.get(true)).isEqualTo(3);   // male
        assertThat(partition.get(false)).isEqualTo(2);  // female
    }
}
